"""Combine independently measured p95 values into an explicit pre-integration budget."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import Any

from arch.benchmarks.reporting import write_json_report


def parse_args() -> argparse.Namespace:
    """Parse component reports generated by the three benchmark scripts."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--asr", type=Path, required=True)
    parser.add_argument("--llm", type=Path, required=True)
    parser.add_argument("--tts", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    return parser.parse_args()


def load(path: Path) -> dict[str, Any]:
    """Load one JSON report and fail before producing an ambiguous budget."""
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as error:
        raise SystemExit(f"Component report does not exist: {path}") from error


def p95(report: dict[str, Any], key: str) -> float:
    """Read a p95 duration from a known report field."""
    value = report.get(key, {}).get("p95_seconds")
    if not isinstance(value, (int, float)):
        raise SystemExit(f"Report is missing {key}.p95_seconds")
    return float(value)


def main() -> None:
    """Write a clearly labelled estimated budget, not a fabricated end-to-end result."""
    args = parse_args()
    asr = load(args.asr)
    llm = load(args.llm)
    tts = load(args.tts)
    component_p95 = {
        "asr_seconds": p95(asr, "inference_seconds"),
        "llm_first_content_seconds": p95(llm, "first_content_seconds"),
        "tts_output_ready_seconds": p95(tts, "output_ready_seconds"),
    }
    estimated_seconds = sum(component_p95.values())
    write_json_report(
        args.output,
        {
            "benchmark": "pipeline_budget_estimate",
            "component_p95_seconds": component_p95,
            "estimated_speech_end_to_audio_ready_seconds": estimated_seconds,
            "target_seconds": 1.5,
            "meets_target": estimated_seconds <= 1.5,
            "note": (
                "This is a pre-integration additive budget. Milestone 2 must measure browser "
                "playback end-to-end."
            ),
        },
    )


if __name__ == "__main__":
    main()
